172					TagsSetting: &v1pb.UserSetting_TagsSetting{Tags: map[string]*v1pb.UserSetting_TagMetadata{}},
173				}
174			default:
175				return nil
176			}
177			return setting
178		}
179	
180		settingKey := convertSettingKeyFromStore(storeSetting.Key)
181		setting := &v1pb.UserSetting{
182			Name: fmt.Sprintf("%s/settings/%s", BuildUserName(user.Username), settingKey),
183		}
184	
185		switch storeSetting.Key {
186		case storepb.UserSetting_GENERAL:
187			if general := storeSetting.GetGeneral(); general != nil {
188				setting.Value = &v1pb.UserSetting_GeneralSetting_{
189					GeneralSetting: &v1pb.UserSetting_GeneralSetting{
190						Locale:         general.Locale,
191						MemoVisibility: general.MemoVisibility,
192						Theme:          general.Theme,
193					},
194				}
195			} else {
196				setting.Value = &v1pb.UserSetting_GeneralSetting_{
197					GeneralSetting: getDefaultUserGeneralSetting(),
198				}
199			}
200		case storepb.UserSetting_WEBHOOKS:
201			webhooks := storeSetting.GetWebhooks()
202			apiWebhooks := make([]*v1pb.UserWebhook, 0)
203			if webhooks != nil {
204				apiWebhooks = make([]*v1pb.UserWebhook, 0, len(webhooks.Webhooks))
205				for _, webhook := range webhooks.Webhooks {
206					apiWebhook := &v1pb.UserWebhook{
207						Name:             fmt.Sprintf("%s/webhooks/%s", BuildUserName(user.Username), webhook.Id),
208						Url:              webhook.Url,
209						DisplayName:      webhook.Title,
210						SigningSecretSet: webhook.SigningSecret != "",
211					}
212					apiWebhooks = append(apiWebhooks, apiWebhook)
213				}
214			}
215			setting.Value = &v1pb.UserSetting_WebhooksSetting_{
216				WebhooksSetting: &v1pb.UserSetting_WebhooksSetting{
217					Webhooks: apiWebhooks,
218				},
219			}
220		case storepb.UserSetting_TAGS:
221			setting.Value = &v1pb.UserSetting_TagsSetting_{
222				TagsSetting: convertUserTagsSettingFromStore(storeSetting.GetTags()),
223			}
224		default:
